def vgg_conv_block(x, num_convs, filters):
    for _ in range(num_convs):
        x = Conv2D(filters, (3, 3), padding='same', activation='relu')(x)
    x = MaxPooling2D((2, 2), strides=(2, 2))(x)
    return x

